// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  interpolate,
  spring,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadPlayfair = makeLoadFont('PlayfairDisplay');

// Module-level font loading
const { fontFamily: playfairFamily } = loadPlayfair();



export type GoldPanProps = Record<string, any>;

// Background Water Waves Component
const WaveLayer: React.FC<{
  speed: number;
  yOffset: number;
  color: string;
  scaleY: number;
  frame: number;
}> = ({ speed, yOffset, color, scaleY, frame }) => {
  const shift = (frame * speed) % 1920;
  return (
    <div
      style={{
        position: "absolute",
        top: yOffset,
        left: -shift,
        width: 1920 * 2,
        height: 1080,
        transition: "none",
      }}
    >
      <svg
        viewBox={`0 0 ${1920 * 2} 1080`}
        preserveAspectRatio="none"
        style={{ width: "100%", height: "100%", transition: "none" }}
      >
        <path
          d={`M 0 50 
             C 480 ${50 - 100 * scaleY}, 480 ${50 + 100 * scaleY}, 960 50 
             C 1440 ${50 - 100 * scaleY}, 1440 ${50 + 100 * scaleY}, 1920 50 
             C 2400 ${50 - 100 * scaleY}, 2400 ${50 + 100 * scaleY}, 2880 50 
             C 3360 ${50 - 100 * scaleY}, 3360 ${50 + 100 * scaleY}, 3840 50 
             L 3840 1080 L 0 1080 Z`}
          fill={color}
        />
      </svg>
    </div>
  );
};

const GoldPanAnimation: React.FC<GoldPanProps> = ({
  backgroundColor = "#87CEEB",
  transparentBackground = false,
  durationInSeconds = 10,
  titleText = "EUREKA!",
  waterColor = "#1B4F72",
  waterHighlight = "#2874A6",
  panColor = "#2C3E50",
  dirtColor = "#5D4037",
  diamondColor = "#00FFFF",
  skinColor = "#F5CBA7",
  sleeveColor = "#C0392B",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Timings
  const swishPhaseEnd = 160;
  const washPhaseStart = 60;
  const washPhaseEnd = 180;
  const liftStartFrame = 210;
  const textStartFrame = 230;

  // Animations - Pan Motion
  const swishIntensity = interpolate(frame, [120, swishPhaseEnd], [1, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const swishX = Math.sin(frame * 0.4) * 100 * swishIntensity;
  const swishY = Math.cos(frame * 0.8) * 30 * swishIntensity;
  const panRotation = Math.sin(frame * 0.4) * 15 * swishIntensity;

  // Animations - Lift & Reveal
  const liftProgress = spring({
    frame: Math.max(0, frame - liftStartFrame),
    fps,
    config: { damping: 14, stiffness: 60 },
  });
  const liftY = liftProgress * -300;
  const liftTilt = liftProgress * 20;
  const panScale = 1 + liftProgress * 0.3;

  // Pan Transform Assembly
  const cx = width / 2 + swishX;
  const cy = height * 0.65 + swishY + liftY;
  const currentAngle = panRotation + liftTilt;

  // Arm IK Calculations (Attaching hands to pan edges)
  const angleRad = currentAngle * (Math.PI / 180);
  const panRadius = 280 * panScale;
  const leftTargetX = cx - panRadius * Math.cos(angleRad);
  const leftTargetY = cy - panRadius * Math.sin(angleRad);
  const rightTargetX = cx + panRadius * Math.cos(angleRad);
  const rightTargetY = cy + panRadius * Math.sin(angleRad);

  // Dirt & Washing Math
  const dirtOpacity = interpolate(
    frame,
    [washPhaseStart, washPhaseEnd],
    [1, 0],
    {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    }
  );
  const washSweep = (frame * 18) % 1000;
  const washOpacity = interpolate(
    frame,
    [washPhaseStart, washPhaseEnd - 20],
    [0.8, 0],
    {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    }
  );

  // Diamond Math
  const diamondReveal = spring({
    frame: Math.max(0, frame - 180),
    fps,
    config: { damping: 12, stiffness: 70 },
  });

  // Text Math
  const textSpring = spring({
    frame: Math.max(0, frame - textStartFrame),
    fps,
    config: { damping: 12 },
  });

  // Small rocks positions to give dirt texture
  const rocks = [
    { x: "20%", y: "30%", r: 15 },
    { x: "70%", y: "20%", r: 25 },
    { x: "40%", y: "60%", r: 10 },
    { x: "80%", y: "50%", r: 20 },
    { x: "15%", y: "70%", r: 18 },
    { x: "55%", y: "35%", r: 12 },
  ];

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, transition: "none" }}>
      {/* 1. Back Water Layer */}
      <WaveLayer
        speed={2}
        yOffset={height * 0.45}
        color={waterColor}
        scaleY={0.5}
        frame={frame}
      />

      {/* 2. The Prospector (Man Silhouette in Background) */}
      <div
        style={{
          position: "absolute",
          left: "50%",
          top: height * 0.2,
          transform: `translateX(-50%) translateY(${
            Math.sin(frame * 0.1) * 10
          }px)`,
          opacity: 0.85,
          transition: "none",
        }}
      >
        {/* Torso */}
        <div
          style={{
            width: 320,
            height: 400,
            backgroundColor: sleeveColor,
            borderRadius: "160px 160px 0 0",
            transition: "none",
          }}
        />
        {/* Head */}
        <div
          style={{
            position: "absolute",
            top: -100,
            left: 110,
            width: 100,
            height: 120,
            backgroundColor: skinColor,
            borderRadius: "50%",
            transition: "none",
          }}
        />
        {/* Hat Brim */}
        <div
          style={{
            position: "absolute",
            top: -120,
            left: 20,
            width: 280,
            height: 40,
            backgroundColor: "#4E342E",
            borderRadius: "50%",
            transition: "none",
          }}
        />
        {/* Hat Crown */}
        <div
          style={{
            position: "absolute",
            top: -180,
            left: 90,
            width: 140,
            height: 80,
            backgroundColor: "#4E342E",
            borderRadius: "70px 70px 0 0",
            transition: "none",
          }}
        />
      </div>

      {/* 3. Mid Water Layer */}
      <WaveLayer
        speed={4}
        yOffset={height * 0.55}
        color={waterHighlight}
        scaleY={0.8}
        frame={frame}
      />

      {/* 4. Front Water Layer */}
      <WaveLayer
        speed={6}
        yOffset={height * 0.75}
        color={waterColor}
        scaleY={1.2}
        frame={frame}
      />

      {/* 5. The Gold Pan & Contents */}
      <div
        style={{
          position: "absolute",
          left: cx - 300,
          top: cy - 200,
          width: 600,
          height: 400,
          borderRadius: "50%",
          backgroundColor: panColor,
          transform: `rotate(${currentAngle}deg) scale(${panScale})`,
          border: `24px solid ${panColor}`,
          borderTopColor: "#1A252F", // Fake 3D lighting edge
          boxShadow:
            "0 30px 60px rgba(0,0,0,0.6), inset 0 20px 60px rgba(0,0,0,0.8)",
          overflow: "hidden",
          transition: "none",
          transformOrigin: "center center",
        }}
      >
        {/* Pan Inner Shadow */}
        <div
          style={{
            position: "absolute",
            width: "90%",
            height: "90%",
            top: "5%",
            left: "5%",
            borderRadius: "50%",
            backgroundColor: "rgba(0,0,0,0.3)",
            pointerEvents: "none",
            transition: "none",
          }}
        />

        {/* Dirt Layer */}
        <div
          style={{
            position: "absolute",
            width: "100%",
            height: "100%",
            backgroundColor: dirtColor,
            opacity: dirtOpacity,
            borderRadius: "50%",
            transition: "none",
          }}
        >
          {rocks.map((rock, i) => (
            <div
              key={i}
              style={{
                position: "absolute",
                left: rock.x,
                top: rock.y,
                width: rock.r * 2,
                height: rock.r * 2,
                backgroundColor: "#3E2723",
                borderRadius: "50%",
                transition: "none",
              }}
            />
          ))}
        </div>

        {/* Diamond Layer */}
        <div
          style={{
            position: "absolute",
            left: "50%",
            top: "50%",
            transform: `translate(-50%, -50%) scale(${diamondReveal})`,
            transition: "none",
          }}
        >
          {/* Sparkles / Glowing Aura */}
          <div
            style={{
              position: "absolute",
              top: "50%",
              left: "50%",
              width: 800,
              height: 800,
              marginLeft: -400,
              marginTop: -400,
              transform: `rotate(${frame * 2}deg)`,
              opacity: interpolate(diamondReveal, [0, 1], [0, 0.4]),
              pointerEvents: "none",
              transition: "none",
            }}
          >
            <svg
              viewBox="0 0 100 100"
              style={{ width: "100%", height: "100%", transition: "none" }}
            >
              <defs>
                <radialGradient id="diamondGlow" cx="50%" cy="50%" r="50%">
                  <stop offset="0%" stopColor="#FFFFFF" stopOpacity="1" />
                  <stop offset="100%" stopColor="#FFFFFF" stopOpacity="0" />
                </radialGradient>
              </defs>
              <circle cx="50" cy="50" r="40" fill="url(#diamondGlow)" />
              {Array.from({ length: 12 }).map((_, i) => (
                <polygon
                  key={i}
                  points="49,50 50,0 51,50"
                  fill="url(#diamondGlow)"
                  transform={`rotate(${i * 30} 50 50)`}
                  opacity={i % 2 === 0 ? 0.9 : 0.5}
                />
              ))}
            </svg>
          </div>

          {/* Actual Diamond SVG */}
          <svg
            width="160"
            height="120"
            viewBox="0 0 160 120"
            style={{
              filter: `drop-shadow(0 0 20px ${diamondColor})`,
              transition: "none",
            }}
          >
            <polygon
              points="40,0 120,0 160,40 80,120 0,40"
              fill={diamondColor}
            />
            {/* Facets */}
            <polygon points="40,0 120,0 80,40" fill="rgba(255,255,255,0.7)" />
            <polygon points="0,40 40,0 80,40" fill="rgba(255,255,255,0.4)" />
            <polygon points="160,40 120,0 80,40" fill="rgba(0,0,0,0.2)" />
            <polygon points="0,40 80,40 80,120" fill="rgba(255,255,255,0.3)" />
            <polygon points="160,40 80,40 80,120" fill="rgba(0,0,0,0.4)" />
          </svg>
        </div>

        {/* Washing Water Effect (Overlays dirt) */}
        <div
          style={{
            position: "absolute",
            top: 0,
            left: washSweep - 300,
            width: 300,
            height: "100%",
            background: `linear-gradient(to right, rgba(255,255,255,0), ${waterHighlight}, rgba(255,255,255,0))`,
            transform: "skewX(-30deg)",
            opacity: washOpacity,
            mixBlendMode: "screen",
            transition: "none",
          }}
        />
      </div>

      {/* 6. Arms & Hands Overlays */}
      <svg
        width="100%"
        height="100%"
        style={{ position: "absolute", pointerEvents: "none", zIndex: 10, transition: "none" }}
      >
        {/* Left Arm */}
        <path
          d={`M -100, ${height + 200} Q 200, ${height + 50} ${leftTargetX}, ${leftTargetY}`}
          fill="none"
          stroke={sleeveColor}
          strokeWidth={100}
          strokeLinecap="round"
          style={{ transition: "none" }}
        />
        {/* Left Hand */}
        <circle
          cx={leftTargetX}
          cy={leftTargetY}
          r={50}
          fill={skinColor}
          style={{ transition: "none" }}
        />

        {/* Right Arm */}
        <path
          d={`M ${width + 100}, ${height + 200} Q ${width - 200}, ${height + 50} ${rightTargetX}, ${rightTargetY}`}
          fill="none"
          stroke={sleeveColor}
          strokeWidth={100}
          strokeLinecap="round"
          style={{ transition: "none" }}
        />
        {/* Right Hand */}
        <circle
          cx={rightTargetX}
          cy={rightTargetY}
          r={50}
          fill={skinColor}
          style={{ transition: "none" }}
        />
      </svg>

      {/* 7. Victory Text Overlay */}
      <div
        style={{
          position: "absolute",
          top: height * 0.15,
          width: "100%",
          textAlign: "center",
          fontFamily: playfairFamily,
          fontSize: 160,
          fontWeight: "bold",
          color: "#FFFFFF",
          textShadow: "0 15px 40px rgba(0,0,0,0.6)",
          transform: `scale(${textSpring}) translateY(${interpolate(
            textSpring,
            [0, 1],
            [100, 0]
          )}px)`,
          opacity: interpolate(textSpring, [0, 0.5], [0, 1]),
          zIndex: 20,
          transition: "none",
        }}
      >
        {titleText}
      </div>
    </AbsoluteFill>
  );
};

export default GoldPanAnimation;